import React, { useEffect, useRef, useState } from 'react';
import { Badge, Spinner, Button } from 'react-bootstrap';
import ModelViewBox from '../../components/Atom/ModelViewBox';
import FormLayout from '../../utils/formLayout';
import { petrolAllowanceContainer } from './formFieldData';
import Table from '../../components/Table';
import { dateConversion, findArrObj, showConfirmationDialog, showMessage } from '../../utils/AllFunction';
import { createPetrolAllowanceRequest, getVisitPlacesRequest, getActivityRequest, getStaffRequest, getPetrolAllowanceRequest, resetCreatePetrolAllowance, resetGetVisitPlaces, resetGetActivity, resetGetStaff, resetGetPetrolAllowance, resetUpdatePetrolAllowance, updatePetrolAllowanceRequest, resetGetBranch, getBranchRequest, getBranchLocationEntryLogsRequest, resetGetBranchLocationEntryLogs } from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks'
import { NotificationContainer } from 'react-notifications';
import _ from 'lodash';
import moment from 'moment';
import noProfile from '../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../api/ApiConfig';
import { useNavigate } from 'react-router-dom';
import Select from 'react-select';

let isEdit = false;

const consolidateRows = (list) => {
    if (!list || list.length === 0) return [];

    const grouped = {};
    list.forEach(item => {
        const dateVal = item.type === 'visitor' ? item.entryDate : item.allowanceDate;
        const dateStr = dateVal ? moment(dateVal).format('YYYY-MM-DD') : 'no-date';
        const key = `${item.staffId || 'no-staff'}_${dateStr}`;

        if (!grouped[key]) {
            grouped[key] = [];
        }
        grouped[key].push(item);
    });

    const consolidated = Object.values(grouped).map(group => {
        if (group.length === 1) {
            const item = group[0];
            const hasVisitor = item.type === 'visitor' && item.entryTime && item.visitOutTime;
            return {
                ...item,
                totalVisits: hasVisitor ? 1 : 0,
                totalKm: hasVisitor ? (Number(item.totalKm) || 0) : (Number(item.total_km || item.totalKm) || 0)
            };
        }

        const hasVisitor = group.some(item => item.type === 'visitor' && item.entryTime && item.visitOutTime);
        const baseItem = group.find(item => item.type === 'visitor') || group[0];

        const staffName = group.find(item => item.type === 'petrol')?.staffName || 
                          group.find(item => item.type === 'visitor')?.staffFullName ||
                          group.find(item => item.type === 'visitor')?.employeeName ||
                          baseItem.staffName ||
                          baseItem.staffFullName ||
                          baseItem.employeeName;

        const dateVal = group.find(item => item.type === 'visitor')?.entryDate || 
                        group.find(item => item.type === 'petrol')?.allowanceDate;

        const fromPlaces = [];
        group.forEach(item => {
            const place = item.type === 'visitor' ? item.registeredBranchName : item.fromPlace;
            if (place && !fromPlaces.includes(place)) {
                fromPlaces.push(place);
            }
        });

        const toPlaces = [];
        group.forEach(item => {
            const place = item.type === 'visitor' ? item.officeName : item.toPlace;
            if (place && !toPlaces.includes(place)) {
                toPlaces.push(place);
            }
        });

        const activities = [];
        group.forEach(item => {
            const act = item.type === 'visitor' ? item.status : item.activityName;
            if (act) {
                const parts = act.split(/[\&,]+/).map(s => s.trim());
                parts.forEach(p => {
                    if (p && !activities.includes(p)) {
                        activities.push(p);
                    }
                });
            }
        });

        let totalKm = 0;
        let totalVisits = 0;
        group.forEach(item => {
            const km = item.type === 'visitor' ? (Number(item.totalKm) || 0) : (Number(item.total_km || item.totalKm) || 0);
            totalKm += km;
            if (item.type === 'visitor' && item.entryTime && item.visitOutTime) {
                totalVisits++;
            }
        });

        return {
            ...baseItem,
            type: hasVisitor ? 'visitor' : 'petrol',
            staffId: baseItem.staffId,
            staffCode: baseItem.staffCode,
            staffProfile: baseItem.staffProfile,
            staffName: staffName,
            staffFullName: staffName,
            employeeName: staffName,
            entryDate: dateVal,
            allowanceDate: dateVal,
            fromPlace: fromPlaces.join(', '),
            registeredBranchName: fromPlaces.join(', '),
            toPlace: toPlaces.join(', '),
            officeName: toPlaces.join(', '),
            activityName: activities.join(' & '),
            status: activities.join(' & '),
            totalKm: parseFloat(totalKm.toFixed(2)),
            total_km: parseFloat(totalKm.toFixed(2)),
            totalVisits: totalVisits,
            createdAt: group[0].createdAt,
            petrolAllowanceId: group.find(item => item.type === 'petrol')?.petrolAllowanceId || baseItem.petrolAllowanceId
        };
    });

    consolidated.sort((a, b) => {
        const dateA = a.type === 'visitor' ? a.entryDate : a.allowanceDate;
        const dateB = b.type === 'visitor' ? b.entryDate : b.allowanceDate;
        return new Date(dateB) - new Date(dateA);
    });

    return consolidated;
};

function Index() {

    usePageTitle({
        title: 'Allowance',
        breadCrumbItems: [
            {
                path: '/allowance/visit-entry',
                label: 'Allowance',
            },
            {
                path: '/allowance/visit-entry',
                label: 'Visit Entry',
                active: true,
            },
        ],
    });

    const navigate = useNavigate();
    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'label', "Visit Entry");
    const accessIds = (pageAccessData?.[0]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)
    const staffId = localData?.[0]?.staffId; // for role Permission (1.superadmin)
    const staffViewFlag = localData?.[0]?.staffViewFlag; // for role Permission (1.superadmin)

    const {
        getBranchSuccess, getBranchList, getBranchFailure,
        getPetrolAllowanceSuccess, getPetrolAllowanceList, getPetrolAllowanceFailure,
        getActivitySuccess, getActivityList, getActivityFailure,
        getVisitPlacesSuccess, getVisitPlacesList, getVisitPlacesFailure,
        createPetrolAllowanceSuccess, createPetrolAllowanceData, createPetrolAllowanceFailure,
        updatePetrolAllowanceSuccess, updatePetrolAllowanceData, updatePetrolAllowanceFailure,
        errorMessage, getStaffSuccess,
        getStaffList,
        getStaffFailure,
        getBranchLocationEntryLogsSuccess,
        getBranchLocationEntryLogsList,
        getBranchLocationEntryLogsFailure,

    } = appSelector((state) => ({

        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,

        getStaffSuccess: state.staffReducer.getStaffSuccess,
        getStaffList: state.staffReducer.getStaffList,
        getStaffFailure: state.staffReducer.getStaffFailure,

        getPetrolAllowanceSuccess: state.petrolAllowanceReducer.getPetrolAllowanceSuccess,
        getPetrolAllowanceList: state.petrolAllowanceReducer.getPetrolAllowanceList,
        getPetrolAllowanceFailure: state.petrolAllowanceReducer.getPetrolAllowanceFailure,

        getActivitySuccess: state.activityReducer.getActivitySuccess,
        getActivityList: state.activityReducer.getActivityList,
        getActivityFailure: state.activityReducer.getActivityFailure,

        getVisitPlacesSuccess: state.visitPlacesReducer.getVisitPlacesSuccess,
        getVisitPlacesList: state.visitPlacesReducer.getVisitPlacesList,
        getVisitPlacesFailure: state.visitPlacesReducer.getVisitPlacesFailure,

        createPetrolAllowanceSuccess: state.petrolAllowanceReducer.createPetrolAllowanceSuccess,
        createPetrolAllowanceData: state.petrolAllowanceReducer.createPetrolAllowanceData,
        createPetrolAllowanceFailure: state.petrolAllowanceReducer.createPetrolAllowanceFailure,

        updatePetrolAllowanceSuccess: state.petrolAllowanceReducer.updatePetrolAllowanceSuccess,
        updatePetrolAllowanceData: state.petrolAllowanceReducer.updatePetrolAllowanceData,
        updatePetrolAllowanceFailure: state.petrolAllowanceReducer.updatePetrolAllowanceFailure,

        errorMessage: state.petrolAllowanceReducer.errorMessage,

        getBranchLocationEntryLogsSuccess: state.staffGeolocationsReducer.getBranchLocationEntryLogsSuccess,
        getBranchLocationEntryLogsList: state.staffGeolocationsReducer.getBranchLocationEntryLogsList,
        getBranchLocationEntryLogsFailure: state.staffGeolocationsReducer.getBranchLocationEntryLogsFailure,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: 'Date',
            accessor: 'allowanceDate',
            Cell: ({ row }) => {
                const dateVal = row.original.type === 'visitor' ? row.original.entryDate : row.original.allowanceDate;
                return (
                    <div>
                        {dateConversion(dateVal, "DD-MM-YYYY")}
                    </div>
                )
            },
        },
        {
            Header: 'Staff',
            accessor: 'staffName',
            Cell: ({ row }) => {
                const staffNameVal = row.original.type === 'visitor'
                    ? (row.original.staffFullName || row.original.employeeName)
                    : row.original.staffName;
                return (
                    <div className="inbox-item-img" style={{ display: 'flex', alignItems: 'center' }}>
                        <img
                            src={row?.original?.staffProfile ? `${baseURL}${row?.original.staffProfile}` : noProfile}
                            alt="staffProfile"
                            className="rounded-circle"
                            crossOrigin="anonymous"
                            onError={(e) => {
                                e.target.onerror = null;
                                e.target.src = noProfile;
                            }}
                            style={{ width: "40px", height: "40px", objectFit: "cover", marginRight: "10px" }}
                        />
                        <div>
                            <div style={{ fontSize: '15px', fontWeight: '600' }}>
                                {staffNameVal}
                            </div>
                            <div style={{ fontSize: '12px', color: '#888' }}>
                                {row?.original?.staffCode}
                            </div>
                        </div>
                    </div>
                )
            }
        },
        {
            Header: 'Total Visits',
            accessor: 'totalVisits',
            Cell: ({ row }) => {
                return (
                    <div>
                        {row.original.totalVisits || 0}
                    </div>
                )
            }
        },
        {
            Header: 'Total KM',
            accessor: 'totalKm',
            Cell: ({ row }) => {
                const totalKmVal = row.original.type === 'visitor' ? row.original.totalKm : (row.original.total_km || row.original.totalKm);
                return (
                    <div>
                        {totalKmVal !== undefined ? Number(totalKmVal).toFixed(2) : '0.00'}
                    </div>
                )
            }
        },
        {
            Header: 'Actions',
            accessor: 'actions',
            Cell: ({ row }) => {
                return (
                    <div style={{ display: 'flex', alignItems: 'center' }}>
                        <span
                            className="text-primary me-2 cursor-pointer"
                            onClick={(e) => {
                                e.stopPropagation();
                                handleRowClick(row.original);
                            }}
                            title="History / Visits"
                        >
                            <i className="fe-eye" style={{ fontSize: '18px' }}></i>
                        </span>
                    </div>
                );
            },
        },
    ];

    const [state, setState] = useState({
        branchId: branchIdforRole,
        minmumFrom: moment().format("YYYY-MM-DD"),
        minmumTo: moment().format("YYYY-MM-DD"),
        allowanceDate: moment().format("YYYY-MM-DD")
    });
    const [parentList, setParentList] = useState([]);
    const [optionListState, setOptionListState] = useState({
        staffList: [],
        branchList: [],
    })
    const [formContain, setFormContain] = useState(petrolAllowanceContainer);
    const [selectedItem, setSelectedItem] = useState({});
    const [selectedIndex, setSelectedIndex] = useState(false);
    const [modal, setModal] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [errors, setErrors] = useState([]);

    const errorHandle = useRef();

    const [filterType, setFilterType] = useState("all");
    const [fromDate, setFromDate] = useState(moment().format("YYYY-MM-DD"));
    const [toDate, setToDate] = useState(moment().format("YYYY-MM-DD"));
    const [selectedFilterStaff, setSelectedFilterStaff] = useState(null);

    const fetchFilteredData = (type, fromDateVal, toDateVal, staffIdVal) => {
        setIsLoading(true);
        const req = {
            ...(branchIdforRole && roleIdforRole != 1 && { branchId: branchIdforRole }),
            ...(staffIdVal && { staffId: staffIdVal })
        };
        const logReq = {
            ...(branchIdforRole && roleIdforRole != 1 && { branchId: branchIdforRole }),
            ...(staffIdVal && { staffId: staffIdVal })
        };

        if (type === 'today') {
            const todayStr = moment().format("YYYY-MM-DD");
            req.fromDate = todayStr;
            req.toDate = todayStr;
            logReq.date = todayStr;
        } else if (type === 'custom') {
            req.fromDate = fromDateVal;
            req.toDate = toDateVal;
            logReq.fromDate = fromDateVal;
            logReq.toDate = toDateVal;
        }

        dispatch(getPetrolAllowanceRequest(req));
        dispatch(getBranchLocationEntryLogsRequest(logReq));
    };

    useEffect(() => {
        setIsLoading(true)
        dispatch(getBranchRequest({ isActive: 1 }));
        
        const req = {
            ...(branchIdforRole && roleIdforRole != 1 && { branchId: branchIdforRole }),
        };
        const logReq = {
            ...(branchIdforRole && roleIdforRole != 1 && { branchId: branchIdforRole }),
        };

        dispatch(getPetrolAllowanceRequest(req));
        dispatch(getBranchLocationEntryLogsRequest(logReq));
        dispatch(getStaffRequest(roleIdforRole != 1 ? { branchId: branchIdforRole } : {}));
        dispatch(getActivityRequest({ isActive: 1 }));
        dispatch(getVisitPlacesRequest({ isActive: 1 }));
    }, []);

    useEffect(() => {
        if (roleIdforRole != 1) {
            let arr = petrolAllowanceContainer;
            const updatedFormFields = _.filter(
                petrolAllowanceContainer[0].formFields,
                (field) => field.name !== 'branchId'
            );
            arr[0].formFields = updatedFormFields;
            setFormContain(arr);
        }
    }, [petrolAllowanceContainer, roleIdforRole]);

    useEffect(() => {
        if (getBranchSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: getBranchList
            })
            dispatch(resetGetBranch())
        } else if (getBranchFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                branchList: [],
            })
            dispatch(resetGetBranch())
        }
    }, [getBranchSuccess, getBranchFailure]);

    useEffect(() => {
        if (getStaffSuccess) {
            setIsLoading(false);
            if (roleIdforRole !== 1) {
                if (!staffViewFlag) {
                    const staffFilter = _.filter(getStaffList, (o) => {
                        return o.staffId == staffId
                    });
                    setOptionListState({
                        ...optionListState,
                        staffList: staffFilter,
                    });
                } else {
                    setOptionListState({
                        ...optionListState,
                        staffList: getStaffList,
                    });
                }
            } else {
                setOptionListState({
                    ...optionListState,
                    staffList: getStaffList,
                });
            }

            dispatch(resetGetStaff());
        } else if (getStaffFailure) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                staffList: [],
            });
            dispatch(resetGetStaff());
        }
    }, [getStaffSuccess, getStaffFailure]);

    useEffect(() => {
        if (getPetrolAllowanceSuccess) {
            setIsLoading(false);
            const rawPetrols = Array.isArray(getPetrolAllowanceList) ? getPetrolAllowanceList : (getPetrolAllowanceList?.data || []);
            const petrols = rawPetrols
                .filter(item => !(typeof item.petrolAllowanceId === 'string' && item.petrolAllowanceId.startsWith('claim-')))
                .map(item => ({ ...item, type: 'petrol' }));
            setParentList(prev => {
                const visitors = prev.filter(item => item.type === 'visitor');
                return consolidateRows([...petrols, ...visitors]);
            });
            dispatch(resetGetPetrolAllowance());
        } else if (getPetrolAllowanceFailure) {
            setIsLoading(false);
            setParentList(prev => consolidateRows(prev.filter(item => item.type === 'visitor')));
            dispatch(resetGetPetrolAllowance());
        }
    }, [getPetrolAllowanceSuccess, getPetrolAllowanceFailure, getPetrolAllowanceList]);

    useEffect(() => {
        if (getBranchLocationEntryLogsSuccess) {
            setIsLoading(false);
            console.log('Branch Location Entry Logs loaded:', getBranchLocationEntryLogsList);
            const logsList = Array.isArray(getBranchLocationEntryLogsList) ? getBranchLocationEntryLogsList : (getBranchLocationEntryLogsList?.data || []);
            const visitors = logsList.map(item => ({ ...item, type: 'visitor' }));
            setParentList(prev => {
                const petrols = prev.filter(item => item.type === 'petrol');
                const result = consolidateRows([...petrols, ...visitors]);
                console.log('Consolidated result:', result);
                return result;
            });
            dispatch(resetGetBranchLocationEntryLogs());
        } else if (getBranchLocationEntryLogsFailure) {
            setIsLoading(false);
            setParentList(prev => consolidateRows(prev.filter(item => item.type === 'petrol')));
            dispatch(resetGetBranchLocationEntryLogs());
        }
    }, [getBranchLocationEntryLogsSuccess, getBranchLocationEntryLogsFailure, getBranchLocationEntryLogsList, dispatch]);

    useEffect(() => {
        if (getActivitySuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                activityList: getActivityList
            })
            dispatch(resetGetActivity())
        } else if (getActivityFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                activityList: []
            })
            dispatch(resetGetActivity())
        }
    }, [getActivitySuccess, getActivityFailure]);

    useEffect(() => {
        if (getVisitPlacesSuccess) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                fromPlaceList: getVisitPlacesList,
                toPlaceList: getVisitPlacesList
            })
            dispatch(resetGetVisitPlaces())
        } else if (getVisitPlacesFailure) {
            setIsLoading(false)
            setOptionListState({
                ...optionListState,
                fromPlaceList: [],
                toPlaceList: []
            })
            dispatch(resetGetVisitPlaces())
        }
    }, [getVisitPlacesSuccess, getVisitPlacesFailure]);



    useEffect(() => {
        if (createPetrolAllowanceSuccess) {
            const newItem = { ...createPetrolAllowanceData[0], type: 'petrol' };
            setParentList(prev => consolidateRows([newItem, ...prev]));
            showMessage('success', 'Created Successfully');
            closeModel();
            dispatch(resetCreatePetrolAllowance());
        } else if (createPetrolAllowanceFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetCreatePetrolAllowance());
        }
    }, [createPetrolAllowanceSuccess, createPetrolAllowanceFailure, createPetrolAllowanceData]);

    useEffect(() => {
        if (updatePetrolAllowanceSuccess) {
            setParentList(prev => {
                const temp_state = [...prev];
                const idToFind = selectedItem.petrolAllowanceId;
                const idxInPetrol = _.findIndex(temp_state, { petrolAllowanceId: idToFind, type: 'petrol' });
                if (idxInPetrol !== -1) {
                    temp_state[idxInPetrol] = { ...updatePetrolAllowanceData[0], type: 'petrol' };
                }
                return consolidateRows(temp_state);
            });
            isEdit && showMessage('success', 'Updated Successfully');
            closeModel();
            dispatch(resetUpdatePetrolAllowance());
        } else if (updatePetrolAllowanceFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdatePetrolAllowance());
        }
    }, [updatePetrolAllowanceSuccess, updatePetrolAllowanceFailure, updatePetrolAllowanceData]);

    const closeModel = () => {
        isEdit = false;
        onFormClear()
        setModal(false)
    }

    const onFormClear = () => {
        setState({
            ...state,
            allowanceDate: moment().format("YYYY-MM-DD"),
            minmumFrom: moment().format("YYYY-MM-DD"),
            staffId: '',
            activityIds: '',
            fromPlace: '',
            branchId: branchIdforRole,
            toPlace: '',
            totalKm: '',
        });
    };

    const createModel = () => {
        onFormClear()
        isEdit = false;
        setModal(true)
    };

    const onEditForm = (data, index) => {
        setState({
            ...state,
            staffId: data?.staffId || "",
            activityIds: data.activityId ? _.map(_.split(data.activityId, ','), _.toNumber) : "",
            fromPlace: data.fromPlaceId,
            toPlace: data.toPlaceId,
            branchId: data?.branchId || branchIdforRole,
            totalKm: data?.total_km || data?.totalKm || "",
            allowanceDate: data.allowanceDate ? dateConversion(data.allowanceDate, "YYYY-MM-DD") : ""
        });
        const branchFilter = {
            branchId: data?.branchId
        }
        dispatch(getStaffRequest(branchFilter));
        isEdit = true;
        setSelectedItem(data)
        setSelectedIndex(index)
        setModal(true)
    };

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    }

    const onFormSubmit = async () => {
        const submitRequest = {
            staffId: state?.staffId || "",
            activityId: state.activityIds ? state.activityIds.toString() : "",
            fromPlace: state.fromPlace ? state.fromPlace.toString() : "",
            branchId: state?.branchId || "",
            toPlace: state.toPlace ? state.toPlace.toString() : "",
            totalKm: state?.totalKm || "",
            allowanceDate: state.allowanceDate ? dateConversion(state.allowanceDate, "YYYY-MM-DD") : "",
        }
        if (isEdit) {
            dispatch(updatePetrolAllowanceRequest(submitRequest, selectedItem.petrolAllowanceId))
        } else {
            dispatch(createPetrolAllowanceRequest(submitRequest))
        }
    };

    const onDeleteForm = (data, index, activeChecker) => {
        const submitRequest = {
            isActive: activeChecker == 0 ? 1 : 0
        }
        setSelectedIndex(index)
        setSelectedItem(data)
        dispatch(updatePetrolAllowanceRequest(submitRequest, data.petrolAllowanceId))
    };

    const onBranchChange = async (option, formName, formUniqueKey, formDisplayKey) => {
        const branchFilter = {
            branchId: option[formUniqueKey]
        }
        setState({
            ...state,
            [formName]: option[formUniqueKey]
        })
        dispatch(getStaffRequest(branchFilter));
    }

    const handleRowClick = (row) => {
        const entry = row.original || row;
        const targetDate = entry.type === 'visitor' ? entry.entryDate : entry.allowanceDate;
        const formattedDate = targetDate ? moment(targetDate).format('YYYY-MM-DD') : '';
        if (entry.staffId && formattedDate) {
            navigate(`/allowance/visit-entry/${entry.staffId}/${formattedDate}`);
        }
    };

    // Prepare staff options for react-select
    const staffOptions = React.useMemo(() => {
        return (optionListState.staffList || []).map(s => ({
            value: s.staffId,
            label: `${s.staffName} (${s.staffCode})`,
            staffName: s.staffName,
            staffCode: s.staffCode,
            staffProfile: s.staffProfileImageName
        }));
    }, [optionListState.staffList]);

    // Custom option component to show profile image
    const customOption = (props) => {
        const { innerRef, innerProps, data, isSelected, isFocused } = props;
        return (
            <div
                ref={innerRef}
                {...innerProps}
                className={`d-flex align-items-center p-2 ${isSelected ? 'bg-primary text-white' : isFocused ? 'bg-light' : ''}`}
                style={{ cursor: 'pointer' }}
            >
                <img
                    src={data.staffProfile ? `${baseURL}${data.staffProfile}` : noProfile}
                    alt="profile"
                    className="rounded-circle me-2"
                    style={{ width: '28px', height: '28px', objectFit: 'cover' }}
                    onError={(e) => {
                        e.target.onerror = null;
                        e.target.src = noProfile;
                    }}
                />
                <div>
                    <div className="fw-semibold" style={{ fontSize: '13px' }}>{data.staffName}</div>
                    <small className={isSelected ? 'text-white-50' : 'text-muted'} style={{ fontSize: '11px' }}>{data.staffCode}</small>
                </div>
            </div>
        );
    };

    // Custom single value component
    const customSingleValue = (props) => {
        const { data } = props;
        return (
            <div className="d-flex align-items-center">
                <img
                    src={data.staffProfile ? `${baseURL}${data.staffProfile}` : noProfile}
                    alt="profile"
                    className="rounded-circle me-2"
                    style={{ width: '20px', height: '20px', objectFit: 'cover' }}
                    onError={(e) => {
                        e.target.onerror = null;
                        e.target.src = noProfile;
                    }}
                />
                <span style={{ fontSize: '13px' }}>{data.label}</span>
            </div>
        );
    };

    // Handle staff selection change
    const handleStaffChange = (selectedOption) => {
        if (selectedOption) {
            setSelectedFilterStaff({
                staffId: selectedOption.value,
                name: selectedOption.staffName,
                code: selectedOption.staffCode
            });
            fetchFilteredData(filterType, fromDate, toDate, selectedOption.value);
        } else {
            setSelectedFilterStaff(null);
            fetchFilteredData(filterType, fromDate, toDate, null);
        }
    };

    const filterToolbar = (
        <div className="d-flex align-items-center gap-3 mb-3 p-3 bg-light rounded border border-light shadow-sm justify-content-between">
            <div className="d-flex align-items-center gap-3 flex-wrap">
                <div>
                    <label className="form-label mb-1 fw-bold text-secondary font-size-12 d-block">Filter Date Mode</label>
                    <div className="btn-group" role="group">
                        <Button
                            variant={filterType === 'all' ? 'primary' : 'outline-primary'}
                            size="sm"
                            onClick={() => {
                                setFilterType('all');
                                fetchFilteredData('all', fromDate, toDate, selectedFilterStaff?.staffId);
                            }}
                        >
                            All
                        </Button>
                        <Button
                            variant={filterType === 'today' ? 'primary' : 'outline-primary'}
                            size="sm"
                            onClick={() => {
                                setFilterType('today');
                                fetchFilteredData('today', fromDate, toDate, selectedFilterStaff?.staffId);
                            }}
                        >
                            Today
                        </Button>
                    </div>
                </div>

                {/* Date Range Selection - Always visible */}
                <div style={{ minWidth: '150px' }}>
                    <label className="form-label mb-1 fw-bold text-secondary font-size-12">From Date</label>
                    <input
                        type="date"
                        className="form-control form-control-sm border-secondary-50"
                        value={fromDate}
                        max={toDate || moment().format("YYYY-MM-DD")}
                        onChange={(e) => {
                            const newFrom = e.target.value;
                            setFromDate(newFrom);
                            if (filterType !== 'all' && filterType !== 'today') {
                                fetchFilteredData('custom', newFrom, toDate, selectedFilterStaff?.staffId);
                            }
                        }}
                    />
                </div>
                <div style={{ minWidth: '150px' }}>
                    <label className="form-label mb-1 fw-bold text-secondary font-size-12">To Date</label>
                    <input
                        type="date"
                        className="form-control form-control-sm border-secondary-50"
                        value={toDate}
                        min={fromDate}
                        max={moment().format("YYYY-MM-DD")}
                        onChange={(e) => {
                            const newTo = e.target.value;
                            setToDate(newTo);
                            if (filterType !== 'all' && filterType !== 'today') {
                                fetchFilteredData('custom', fromDate, newTo, selectedFilterStaff?.staffId);
                            }
                        }}
                    />
                </div>

                {/* Searchable Employee Dropdown using react-select */}
                <div style={{ minWidth: '280px' }}>
                    <label className="form-label mb-1 fw-bold text-secondary font-size-12">Staff Member</label>
                    <Select
                        isClearable
                        isSearchable
                        placeholder="Search employee..."
                        options={staffOptions}
                        value={selectedFilterStaff ? staffOptions.find(opt => opt.value === selectedFilterStaff.staffId) : null}
                        onChange={handleStaffChange}
                        components={{
                            Option: customOption,
                            SingleValue: customSingleValue
                        }}
                        styles={{
                            control: (provided) => ({
                                ...provided,
                                minHeight: '38px',
                                fontSize: '13px'
                            }),
                            menu: (provided) => ({
                                ...provided,
                                zIndex: 1050
                            }),
                            option: (provided, state) => ({
                                ...provided,
                                backgroundColor: state.isSelected ? '#727cf5' : state.isFocused ? '#f8f9fa' : 'white',
                                color: state.isSelected ? 'white' : 'inherit',
                                '&:hover': {
                                    backgroundColor: state.isSelected ? '#727cf5' : '#f8f9fa'
                                }
                            })
                        }}
                        filterOption={(option, inputValue) => {
                            const searchValue = inputValue.toLowerCase();
                            return (
                                option.data.staffName.toLowerCase().includes(searchValue) ||
                                option.data.staffCode.toLowerCase().includes(searchValue)
                            );
                        }}
                        noOptionsMessage={() => "No employees found"}
                    />
                </div>
            </div>
            <div className="text-end">
                <span className="text-muted font-size-12">
                    Viewing records:{' '}
                    <strong className="text-dark">
                        {filterType === 'all' && 'All Dates'}
                        {filterType === 'today' && `Today (${moment().format('DD-MMM-YYYY')})`}
                    </strong>
                    {selectedFilterStaff && (
                        <>
                            {' '}and employee:{' '}
                            <strong className="text-primary">{selectedFilterStaff.name}</strong>
                        </>
                    )}
                </span>
            </div>
        </div>
    );

    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <Table
                    columns={columns}
                    Title={'Visit Entry List'}
                    data={parentList || []}
                    pageSize={25}
                    toggle={(roleIdforRole == 1 || _.includes(accessIds, '1')) ? createModel : false}
                    onClickRow={handleRowClick}
                    isSearchable={false}
                    ifComponent={filterToolbar}
                />}

            <ModelViewBox
                modal={modal}
                setModel={setModal}
                modelHeader={'Visit Entry'}
                modelSize={'md'}
                isEdit={isEdit}
                handleSubmit={handleValidation}>
                <FormLayout
                    dynamicForm={formContain}
                    handleSubmit={onFormSubmit}
                    optionListState={optionListState}
                    setState={setState}
                    onChangeCallBack={{ "onBranchChange": onBranchChange }}
                    state={state}
                    ref={errorHandle}
                    noOfColumns={1}
                    errors={errors}
                    setErrors={setErrors}
                />
            </ModelViewBox>
        </React.Fragment>
    );
}

export default Index;
